def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")

    def read_integer(text):
        # Avoid Python's limit on converting very long decimal strings.
        text = text.strip()
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]

        value = 0
        for start in range(0, len(text), 9):
            part = text[start:start + 9]
            value = value * (10 ** len(part)) + int(part)
        return sign * value

    def parse(formula):
        # Iterative shunting-yard parser: nesting never uses Python recursion.
        nodes = []
        operators = []
        argument_counts = []
        expecting_operand = True

        def reduce_operator():
            operator = operators.pop()
            if operator == "neg":
                nodes.append(("neg", nodes.pop()))
                return

            right = nodes.pop()
            left = nodes.pop()

            if operator == ":":
                first, second = left[1], right[1]
                r1, r2 = int(first[1:]), int(second[1:])
                c1, c2 = ord(first[0]), ord(second[0])
                nodes.append((
                    "range",
                    min(r1, r2), max(r1, r2),
                    min(c1, c2), max(c1, c2),
                ))
            else:
                nodes.append(("binary", operator, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", read_integer(token)))
                expecting_operand = False

            elif token in functions:
                operators.append(token)
                expecting_operand = True

            elif token[0].isalpha():
                nodes.append(("reference", token))
                expecting_operand = False

            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expecting_operand = True

            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expecting_operand = True

            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()

                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]

                    if function == "IF":
                        nodes.append(("if", *arguments))
                    else:
                        nodes.append(("call", function, arguments))

                expecting_operand = False

            else:
                operator = (
                    "neg" if token == "-" and expecting_operand else token
                )
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[operator]:
                        break
                    if (
                        precedence[top] == precedence[operator]
                        and operator == "neg"
                    ):
                        break
                    reduce_operator()

                operators.append(operator)
                expecting_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for node in arguments:
            if node[0] != "range":
                yield node
                continue

            _, first_row, last_row, first_column, last_column = node
            for row in range(first_row, last_row + 1):
                for column in range(first_column, last_column + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def binary(operator, left, right):
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if operator == "=":
            return left == right
        if operator == "<>":
            return left != right
        if operator == "<":
            return left < right
        if operator == "<=":
            return left <= right
        if operator == ">":
            return left > right
        return left >= right

    results = {}
    active = set()

    for root in cells:
        if root in results:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]

                if name in results:
                    values.append(results[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    content = cells[name]
                    if content.startswith("="):
                        active.add(name)
                        tasks.append(("store", name))
                        tasks.append(("node", parse(content[1:])))
                    else:
                        value = read_integer(content)
                        results[name] = value
                        values.append(value)

            elif kind == "store":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif kind == "node":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    values.append(node[1])

                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))

                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("node", node[1]))

                elif node_kind == "binary":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("node", node[2]))

                elif node_kind == "if":
                    tasks.append(("branch", node[2], node[3]))
                    tasks.append(("node", node[1]))

                else:  # SUM, MIN, or MAX
                    tasks.append((
                        "aggregate", node[1],
                        argument_nodes(node[2]), None, False,
                    ))

            elif kind == "negate":
                if not isinstance(values[-1], str):
                    values[-1] = -values[-1]

            elif kind == "left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("node", task[2]))

            elif kind == "right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(binary(task[1], task[2], right))

            elif kind == "branch":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("node", task[1] if condition else task[2]))

            else:  # aggregate
                _, function, iterator, total, consume = task

                if consume:
                    value = values.pop()
                    if isinstance(value, str):
                        values.append(value)
                        continue

                    if total is None:
                        total = value
                    elif function == "SUM":
                        total += value
                    elif function == "MIN":
                        total = min(total, value)
                    else:
                        total = max(total, value)

                next_node = next(iterator, None)
                if next_node is None:
                    values.append(0 if total is None else total)
                else:
                    tasks.append((
                        "aggregate", function, iterator, total, True,
                    ))
                    tasks.append(("node", next_node))

    return {name: results[name] for name in cells}
